import { createWriteStream } from "node:fs";
import { pipeline } from "node:stream/promises";
import { Readable } from "node:stream";

const res = await fetch("https://api.example.com/export.csv");
if (!res.ok) throw new Error(res.statusText);
await pipeline(Readable.fromWeb(res.body), createWriteStream("export.csv"));

const res = await fetch("/api/events");
const reader = res.body.getReader();
const decoder = new TextDecoder();
while (true) {
  const { done, value } = await reader.read();
  if (done) break;
  processChunk(decoder.decode(value, { stream: true }));
}

async function getReport(id, { signal }) {
  const cached = await redis.getBuffer(`report:${id}`);
  if (cached) return new Response(cached);
  const res = await fetch(`/reports/${id}`, { signal });
  const buf = Buffer.from(await res.arrayBuffer());
  await redis.set(`report:${id}`, buf, "EX", 3600);
  return new Response(buf, { headers: res.headers });
}

